import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { randomUUID } from 'node:crypto';

export interface JobRow {
  id: string; status: string; input: string; steps: number; fail_attempts: number;
  attempts: number; progress_completed: number; result_output: string | null; error: string | null;
  created_at: string; updated_at: string;
}

export function initializeDatabase(db: DatabaseSync): void {
  db.exec(`
    CREATE TABLE IF NOT EXISTS jobs (
      id TEXT PRIMARY KEY, status TEXT NOT NULL, input TEXT NOT NULL, steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0,
      progress_completed INTEGER NOT NULL DEFAULT 0, result_output TEXT, error TEXT,
      created_at TEXT NOT NULL, updated_at TEXT NOT NULL, available_at INTEGER NOT NULL DEFAULT 0
    );
    CREATE INDEX IF NOT EXISTS jobs_queue ON jobs(status, available_at, created_at);
    CREATE TABLE IF NOT EXISTS idempotency (
      key TEXT PRIMARY KEY, payload TEXT NOT NULL, job_id TEXT NOT NULL REFERENCES jobs(id)
    );
    CREATE TABLE IF NOT EXISTS worker_state (id INTEGER PRIMARY KEY CHECK(id=1), heartbeat INTEGER NOT NULL);
  `);
}

export function formatJob(row: JobRow): Record<string, unknown> {
  return {
    id: row.id, status: row.status, input: row.input, steps: row.steps,
    failAttempts: row.fail_attempts, attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at, updatedAt: row.updated_at,
  };
}

export function newJobId(): string { return randomUUID(); }

/** Opens the SQLite database shared by the server and worker processes. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  initializeDatabase(db);
  return db;
}
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase, formatJob, newJobId, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const json = (res: ServerResponse, status: number, body: unknown): void => {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
};
const error = (res: ServerResponse, status: number, code: string, message: string, fields?: {field:string;message:string}[]): void =>
  json(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });

async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  let size = 0;
  for await (const chunk of req) {
    const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
    size += buf.length;
    if (size > 1024 * 1024) throw new Error('body_too_large');
    chunks.push(buf);
  }
  return Buffer.concat(chunks).toString('utf8');
}

function validate(value: unknown): { payload?: {input:string;steps:number;failAttempts:number}; fields: {field:string;message:string}[] } {
  const fields: {field:string;message:string}[] = [];
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return { fields: [{ field: 'body', message: 'Must be a JSON object.' }] };
  }
  const obj = value as Record<string, unknown>;
  for (const key of Object.keys(obj)) if (!['input', 'steps', 'failAttempts'].includes(key)) fields.push({ field: key, message: 'Unknown field.' });
  if (typeof obj.input !== 'string') fields.push({ field: 'input', message: 'Must be a string.' });
  else if (obj.input.length < 1 || obj.input.length > 1000 || obj.input.trim().length === 0) fields.push({ field: 'input', message: 'Must contain 1–1000 characters and not be only whitespace.' });
  const steps = obj.steps === undefined ? 5 : obj.steps;
  const failAttempts = obj.failAttempts === undefined ? 0 : obj.failAttempts;
  if (typeof steps !== 'number' || !Number.isInteger(steps) || steps < 1 || steps > 20) fields.push({ field: 'steps', message: 'Must be an integer from 1 to 20.' });
  if (typeof failAttempts !== 'number' || !Number.isInteger(failAttempts) || failAttempts < 0 || failAttempts > 5) fields.push({ field: 'failAttempts', message: 'Must be an integer from 0 to 5.' });
  if (fields.length) return { fields };
  return { payload: { input: obj.input as string, steps: steps as number, failAttempts: failAttempts as number }, fields };
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer(async (req, res) => {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  try {
    if (pathname === '/health') {
      if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
      const row = db.prepare('SELECT heartbeat FROM worker_state WHERE id=1').get() as {heartbeat:number} | undefined;
      return json(res, 200, { status: 'ok', worker: row && Date.now() - row.heartbeat < 3000 ? 'up' : 'down' });
    }
    if (pathname === '/') {
      if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
      res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' }); res.end(uiHtml); return;
    }
    if (pathname === '/api/jobs') {
      if (req.method === 'GET') {
        const rows = db.prepare('SELECT * FROM jobs ORDER BY created_at DESC, rowid DESC').all() as unknown as JobRow[];
        return json(res, 200, { jobs: rows.map(formatJob) });
      }
      if (req.method === 'POST') {
        let raw: string;
        try { raw = await readBody(req); } catch {
          return error(res, 400, 'invalid_request', 'Invalid request.', [{ field: 'body', message: 'Request body is too large.' }]);
        }
        const fields: {field:string;message:string}[] = [];
        if (!/^application\/json(?:\s*;|\s*$)/i.test(req.headers['content-type'] ?? '')) fields.push({ field: 'body', message: 'Content-Type must be application/json.' });
        let parsed: unknown;
        try { parsed = JSON.parse(raw); } catch { fields.push({ field: 'body', message: 'Body must contain valid JSON.' }); }
        const checked = validate(parsed);
        fields.push(...checked.fields);
        const keyHeader = req.headers['idempotency-key'];
        if (keyHeader !== undefined && (Array.isArray(keyHeader) || !/^[A-Za-z0-9_-]{1,128}$/.test(keyHeader))) fields.push({ field: 'Idempotency-Key', message: 'Must contain 1–128 letters, digits, underscores, or hyphens.' });
        const key = typeof keyHeader === 'string' ? keyHeader : undefined;
        if (fields.length || !checked.payload) return error(res, 400, 'invalid_request', 'Request validation failed.', fields);
        const payload = checked.payload;
        const canonical = JSON.stringify(payload);
        db.exec('BEGIN IMMEDIATE');
        try {
          if (key !== undefined) {
            const previous = db.prepare('SELECT payload, job_id FROM idempotency WHERE key=?').get(key) as {payload:string;job_id:string} | undefined;
            if (previous) {
              db.exec('COMMIT');
              if (previous.payload !== canonical) return error(res, 409, 'idempotency_conflict', 'Idempotency key was already used with a different payload.');
              const job = db.prepare('SELECT * FROM jobs WHERE id=?').get(previous.job_id) as unknown as JobRow;
              return json(res, 200, formatJob(job));
            }
          }
          const id = newJobId();
          const now = new Date().toISOString();
          db.prepare(`INSERT INTO jobs (id,status,input,steps,fail_attempts,attempts,progress_completed,created_at,updated_at)
            VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?)`).run(id, payload.input, payload.steps, payload.failAttempts, now, now);
          if (key !== undefined) db.prepare('INSERT INTO idempotency(key,payload,job_id) VALUES(?,?,?)').run(key, canonical, id);
          db.exec('COMMIT');
          const job = db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as unknown as JobRow;
          return json(res, 201, formatJob(job));
        } catch (e) { db.exec('ROLLBACK'); throw e; }
      }
      return error(res, 405, 'method_not_allowed', 'Method not allowed.');
    }
    const match = pathname.match(/^\/api\/jobs\/([^/]+)$/);
    if (match) {
      if (req.method !== 'GET') return error(res, 405, 'method_not_allowed', 'Method not allowed.');
      let id: string;
      try { id = decodeURIComponent(match[1]!); } catch { return error(res, 404, 'not_found', 'Job not found.'); }
      const job = db.prepare('SELECT * FROM jobs WHERE id=?').get(id) as unknown as JobRow | undefined;
      if (!job) return error(res, 404, 'not_found', 'Job not found.');
      return json(res, 200, formatJob(job));
    }
    return error(res, 404, 'not_found', 'Route not found.');
  } catch {
    if (!res.headersSent) error(res, 500, 'internal_error', 'Internal server error.'); else res.end();
  }
});

