import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) process.on(signal, () => { stopping = true; });

// A running row belongs to a worker that no longer holds it. Requeue it on startup;
// progress is reset when the next attempt is claimed.
db.prepare("UPDATE jobs SET status='queued', updated_at=?, available_at=0 WHERE status='running'").run(new Date().toISOString());
const heartbeat = () => db.prepare(`INSERT INTO worker_state(id,heartbeat) VALUES(1,?)
  ON CONFLICT(id) DO UPDATE SET heartbeat=excluded.heartbeat`).run(Date.now());
heartbeat();
const heartbeatTimer = setInterval(heartbeat, 500);

async function processOne(): Promise<boolean> {
  db.exec('BEGIN IMMEDIATE');
  let job: JobRow | undefined;
  try {
    job = db.prepare("SELECT * FROM jobs WHERE status='queued' AND available_at<=? ORDER BY created_at ASC, rowid ASC LIMIT 1").get(Date.now()) as unknown as JobRow | undefined;
    if (job) {
      const now = new Date().toISOString();
      db.prepare("UPDATE jobs SET status='running', attempts=attempts+1, progress_completed=0, updated_at=? WHERE id=? AND status='queued'").run(now, job.id);
      job = db.prepare('SELECT * FROM jobs WHERE id=?').get(job.id) as unknown as JobRow;
    }
    db.exec('COMMIT');
  } catch (e) { db.exec('ROLLBACK'); throw e; }
  if (!job) return false;

  if (job.attempts <= job.fail_attempts) {
    await sleep(100);
    if (stopping) return true;
    const now = new Date().toISOString();
    if (job.attempts >= 3) {
      db.prepare("UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, progress_completed=0, updated_at=? WHERE id=? AND status='running'").run(now, job.id);
    } else {
      db.prepare("UPDATE jobs SET status='queued', error=NULL, result_output=NULL, available_at=?, updated_at=? WHERE id=? AND status='running'").run(Date.now() + 500, now, job.id);
    }
    return true;
  }

  for (let step = 1; step <= job.steps; step++) {
    await sleep(100);
    if (stopping) return true;
    db.prepare("UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'").run(step, new Date().toISOString(), job.id);
  }
  db.prepare("UPDATE jobs SET status='completed', result_output=?, error=NULL, updated_at=? WHERE id=? AND status='running'").run(job.input.toUpperCase(), new Date().toISOString(), job.id);
  return true;
}

console.log('worker started');
while (!stopping) {
  if (!(await processOne())) await sleep(100);
}
clearInterval(heartbeatTimer);
// A graceful stop leaves an interrupted attempt available for the next worker process.
db.prepare("UPDATE jobs SET status='queued', available_at=0, updated_at=? WHERE status='running'").run(new Date().toISOString());
db.close();
