  <h1>Job tracker</h1>
  <form data-testid="job-form" id="job-form">
    <label for="job-input">Input</label>
    <input data-testid="job-input" id="job-input" name="input" type="text" required maxlength="1000">
    <label for="job-steps">Steps</label>
    <input data-testid="job-steps" id="job-steps" name="steps" type="number" min="1" max="20" step="1" value="5">
    <label for="job-fail-attempts">Fail attempts</label>
    <input data-testid="job-fail-attempts" id="job-fail-attempts" name="failAttempts" type="number" min="0" max="5" step="1" value="0">
    <button data-testid="job-submit" type="submit">Submit job</button>
    <div data-testid="form-error" id="form-error" role="alert"></div>
  </form>
  <h2>Jobs</h2>
  <div data-testid="job-list" id="job-list" aria-live="polite"></div>
  <script>
    const form = document.querySelector('[data-testid="job-form"]');
    const errorRegion = document.querySelector('[data-testid="form-error"]');
    const list = document.querySelector('[data-testid="job-list"]');
    function showError(data) {
      const detail = data && data.error;
      const parts = [detail && detail.message || 'Request failed.'];
      if (detail && Array.isArray(detail.fields)) for (const field of detail.fields) parts.push(`${field.field}: ${field.message}`);
      errorRegion.textContent = parts.join('\n');
    }
    form.addEventListener('submit', async event => {
      event.preventDefault(); errorRegion.textContent = '';
      const body = {
        input: document.querySelector('[data-testid="job-input"]').value,
        steps: Number(document.querySelector('[data-testid="job-steps"]').value),
        failAttempts: Number(document.querySelector('[data-testid="job-fail-attempts"]').value)
      };
      try {
        const response = await fetch('/api/jobs', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
        const data = await response.json();
        if (!response.ok) showError(data);
        else { errorRegion.textContent = ''; await refresh(); }
      } catch { errorRegion.textContent = 'Unable to submit job.'; }
    });
    function makeJob(job) {
      const item = document.createElement('article'); item.className = 'job'; item.dataset-testid = 'job-item'; item.dataset.jobId = job.id;
      const title = document.createElement('strong'); title.textContent = job.input; item.append(title);
      const status = document.createElement('p'); status.append('Status: ');
      const statusText = document.createElement('span'); statusText.dataset.testid = 'job-status'; statusText.textContent = job.status; status.append(statusText); item.append(status);
      const progress = document.createElement('p'); progress.append('Progress: ');
      const progressText = document.createElement('span'); progressText.dataset.testid = 'job-progress'; progressText.textContent = `${job.progress.completed}/${job.progress.total}`; progress.append(progressText); item.append(progress);
      const result = document.createElement('p'); result.append('Result: ');
      const resultText = document.createElement('span'); resultText.dataset.testid = 'job-result';
      resultText.textContent = job.status === 'completed' ? job.result.output : job.status === 'failed' ? job.error : '';
      result.append(resultText); item.append(result);
      return item;
    }
    async function refresh() {
      try {
        const response = await fetch('/api/jobs'); if (!response.ok) return;
        const data = await response.json();
        const fragment = document.createDocumentFragment();
        for (const job of data.jobs) fragment.append(makeJob(job));
        list.replaceChildren(fragment);
      } catch { /* A later poll will refresh after a temporary connection error. */ }
    }
    refresh(); setInterval(refresh, 700);
  </script>
</body>
